def longestAlmostPalindrome(s: str) -> int:
    n = len(s)
    if n <= 2:
        return n
    max_len = 1
    def expand(left: int, right: int) -> int:
        mismatches = 0
        l, r = left, right
        cur_len = 0
        while l >= 0 and r < n:
            if s[l] != s[r]:
                mismatches += 1
                if mismatches > 1:
                    break
            cur_len = r - l + 1
            l -= 1
            r += 1
        return cur_len

    for i in range(n):
        max_len = max(max_len, expand(i, i))
        max_len = max(max_len, expand(i, i + 1))
    return max_len

#include <string>
#include <algorithm>

class Solution {
public:
    int longestAlmostPalindrome(std::string s) {
        int n = s.length();
        if (n <= 2) return n;
        int maxLen = 1;
        auto expand = [&](int left, int right) {
            int mismatches = 0;
            int l = left, r = right;
            int curLen = 0;
            while (l >= 0 && r < n) {
                if (s[l] != s[r]) {
                    mismatches++;
                    if (mismatches > 1) break;
                }
                curLen = r - l + 1;
                l--;
                r++;
            }
            return curLen;
        };
        for (int i = 0; i < n; ++i) {
            maxLen = std::max(maxLen, expand(i, i));
            maxLen = std::max(maxLen, expand(i, i + 1));
        }
        return maxLen;
    }
};

class Solution {
    public int longestAlmostPalindrome(String s) {
        int n = s.length();
        if (n <= 2) return n;
        int maxLen = 1;
        for (int i = 0; i < n; i++) {
            maxLen = Math.max(maxLen, expand(s, n, i, i));
            maxLen = Math.max(maxLen, expand(s, n, i, i + 1));
        }
        return maxLen;
    }

    private int expand(String s, int n, int left, int right) {
        int mismatches = 0;
        int l = left, r = right;
        int curLen = 0;
        while (l >= 0 && r < n) {
            if (s.charAt(l) != s.charAt(r)) {
                mismatches++;
                if (mismatches > 1) break;
            }
            curLen = r - l + 1;
            l--;
            r++;
        }
        return curLen;
    }
}

